-- Generated by Claude
--------------------------------------------------------------------------
-- UIScript.lua
--
-- Drives the front-end UI flow: Main Menu -> HUD -> Game Over -> Pause,
-- keyed off _G.GameState ("MENU" | "PLAYING" | "GAMEOVER" | "PAUSED").
--
-- Every modal (Main Menu, Game Over, Pause) and the HUD are wrapped in a 
-- small `Popup` state machine (HIDDEN -> OPENING -> IDLE -> CLOSING -> HIDDEN).
-- Clicking buttons tells the popup to play its close animation first, 
-- and only fires the state-change callback once fully finished.
--------------------------------------------------------------------------

local GLOBAL_FONT = "Fonts/DenkOne-Regular.ttf"

local function NewVec2(x, y) return Math.Vec2.new(x, y) end
local function NewVec4(r, g, b, a) return Math.Vec4.new(r, g, b, a) end

--------------------------------------------------------------------------
-- Tunables
--------------------------------------------------------------------------
local HIDDEN_OFFSET_Y = -9999.0   -- parks a popup far off-screen while hidden

local MENU_BASE_SIZE     = NewVec2(620, 560)
local GAMEOVER_BASE_SIZE = NewVec2(620, 520)
local PAUSE_BASE_SIZE    = NewVec2(620, 520)
local HUD_SIZE           = NewVec2(800, 100)
local HUD_OFFSET_Y       = 20.0

local POPUP_BG_COLOR = { r = 0.12, g = 0.12, b = 0.14, a = 0.85 }
local TEXT_WHITE     = NewVec4(1.0, 1.0, 1.0, 1.0)

local MENU_OPEN_SPEED      = 3.2   -- popups/sec, higher = faster spring-in
local MENU_CLOSE_SPEED     = 4.5   -- popups/sec, higher = snappier collapse
local GAMEOVER_OPEN_SPEED  = 3.6
local GAMEOVER_CLOSE_SPEED = 4.8
local PAUSE_OPEN_SPEED     = 3.6
local PAUSE_CLOSE_SPEED    = 4.8
local HUD_OPEN_SPEED       = 5.0

local FLOAT_AMPLITUDE = 8.0    -- px, idle main-menu bob
local FLOAT_SPEED     = 2.0    -- rad/sec

local DROP_HEIGHT           = 80.0  -- px, game-over drop-in distance
local DROP_SETTLE_MUL       = 1.5   -- how much faster the drop settles than the pop
local WOBBLE_AMPLITUDE      = 5.0   -- px, post-impact wobble
local WOBBLE_SPEED          = 2.0   -- rad/sec
local IDLE_WOBBLE_AMPLITUDE = 2.0   -- px, subtle idle "breathing" once settled

local IMPACT_SQUASH  = 0.18    -- vertical compression at the moment of landing
local IMPACT_STRETCH = 0.60    -- horizontal stretch, relative to the squash

local CLOSE_LIFT = 60.0        -- px, upward drift while a popup collapses away

local PUNCH_DECAY    = 6.0     -- per second
local PUNCH_STRENGTH = 0.15    -- extra scale from a full-strength punch

--------------------------------------------------------------------------
-- Math helpers
--------------------------------------------------------------------------
local function Clamp01(t)
    if t < 0.0 then return 0.0 end
    if t > 1.0 then return 1.0 end
    return t
end

local function EaseOutBack(t)
    local c1 = 1.70158
    local c3 = c1 + 1.0
    local p = t - 1.0
    return 1.0 + c3 * (p ^ 3) + c1 * (p ^ 2)
end

local function EaseInBack(t)
    local c1 = 1.70158
    local c3 = c1 + 1.0
    return c3 * (t ^ 3) - c1 * (t ^ 2)
end

--------------------------------------------------------------------------
-- Popup: shared open/idle/close/punch state machine
--------------------------------------------------------------------------
local Popup = {}
Popup.__index = Popup

function Popup.new(container, baseSize, bgColor, openSpeed, closeSpeed, useColor)
    local self = setmetatable({}, Popup)
    self.container  = container
    self.baseSize   = baseSize
    self.bgR        = bgColor and bgColor.r or 0.0
    self.bgG        = bgColor and bgColor.g or 0.0
    self.bgB        = bgColor and bgColor.b or 0.0
    self.bgAlpha    = bgColor and bgColor.a or 1.0
    self.openSpeed  = openSpeed
    self.closeSpeed = closeSpeed
    self.useColor   = (useColor ~= false)
    self.state      = "HIDDEN"
    self.progress   = 0.0
    self.scale      = 0.0
    self.alpha      = 0.0
    self.punch      = 0.0
    self.pendingFn  = nil

    self.container.Offset = NewVec2(0, HIDDEN_OFFSET_Y)
    return self
end

function Popup:IsVisible()
    return self.state ~= "HIDDEN"
end

function Popup:Open()
    if self.state == "HIDDEN" or self.state == "CLOSING" then
        self.state = "OPENING"
        self.progress = 0.0
    end
end

function Popup:Close(onClosed)
    if self.state == "OPENING" or self.state == "IDLE" then
        self.state = "CLOSING"
        self.progress = 0.0
        self.pendingFn = onClosed
    end
end

function Popup:HideInstantly()
    self.state = "HIDDEN"
    self.progress = 0.0
    self.scale = 0.0
    self.alpha = 0.0
    self.punch = 0.0
    self.pendingFn = nil
    self.container.Offset = NewVec2(0, HIDDEN_OFFSET_Y)
end

function Popup:Punch(strength)
    self.punch = math.max(self.punch, strength)
end

function Popup:Update(dt)
    self.punch = math.max(0.0, self.punch - dt * PUNCH_DECAY)

    if self.state == "OPENING" then
        self.progress = Clamp01(self.progress + dt * self.openSpeed)
        self.scale = EaseOutBack(self.progress)
        self.alpha = Clamp01(self.progress * 1.6)

        if self.progress >= 1.0 then
            self.state = "IDLE"
            self.scale = 1.0
            self.alpha = 1.0
        end

    elseif self.state == "CLOSING" then
        self.progress = Clamp01(self.progress + dt * self.closeSpeed)
        self.scale = math.max(0.0, 1.0 - EaseInBack(self.progress))
        self.alpha = Clamp01(1.0 - self.progress * 1.3)

        if self.progress >= 1.0 then
            local onClosed = self.pendingFn
            self:HideInstantly()
            if onClosed then
                onClosed()
            end
        end
    end
end

function Popup:ApplyVisuals(extraOffsetX, extraOffsetY, scaleXMul, scaleYMul)
    scaleXMul = scaleXMul or 1.0
    scaleYMul = scaleYMul or 1.0

    local punchMul = 1.0 + self.punch * PUNCH_STRENGTH
    local sx = self.baseSize.x * self.scale * scaleXMul * punchMul
    local sy = self.baseSize.y * self.scale * scaleYMul * punchMul

    self.container.Size = NewVec2(sx, sy)
    self.container.Offset = NewVec2(extraOffsetX, extraOffsetY)

    if self.useColor then
        local bg = NewVec4(self.bgR, self.bgG, self.bgB, self.bgAlpha * self.alpha)
        self.container.NormalColor = bg
        self.container.HoverColor = bg
        self.container.PressedColor = bg
    end
end

--------------------------------------------------------------------------
-- UI element builder helpers
--------------------------------------------------------------------------

local function ConfigureLabel(text, opts)
    text.Anchor = opts.anchor
    text.Pivot = opts.pivot or NewVec2(0, 0)
    text.FontSize = opts.fontSize
    text.Color = opts.color
    text.TextAlignment = TextAlignment.CENTER
    text.TextVAlignment = TextVerticalAlignment.CENTER
    return text
end

local function ConfigureButton(btn, opts)
    btn.Anchor = opts.anchor
    btn.Pivot = opts.pivot or NewVec2(0.5, 0.5)
    btn.Size = opts.size
    btn.NormalColor  = opts.normal
    btn.HoverColor   = opts.hover
    btn.PressedColor = opts.pressed

    local label = btn:GetText()
    label.FontSize = opts.fontSize
    label.Color = opts.textColor or TEXT_WHITE
    label.TextAlignment = TextAlignment.CENTER
    label.TextVAlignment = TextVerticalAlignment.CENTER

    if opts.onClick then
        btn:OnClick(opts.onClick)
    end

    return btn
end

