local function BuildHUD()
    local container = UIWidget.new()
    container.Anchor = NewVec2(0.5, 0.03)
    container.Pivot = NewVec2(0.5, 0.0)
    container.Size = HUD_SIZE

    local popup = Popup.new(container, HUD_SIZE, nil, HUD_OPEN_SPEED, HUD_OPEN_SPEED, false)

    local hudText = UIText.new("Score: 0 // Lives: 3", GLOBAL_FONT)
    ConfigureLabel(hudText, { anchor = NewVec2(0.5, 0.5), fontSize = 34, color = TEXT_WHITE })
    container:AddChild(hudText)

    local pauseBtn = ConfigureButton(UIButton.new("||", GLOBAL_FONT, ""), {
        anchor = NewVec2(1.0, 0),
        pivot = NewVec2(0.5, 0.5),
        size = NewVec2(55, 55),
        normal = NewVec4(0.18, 0.18, 0.20, 0.85), hover = NewVec4(0.30, 0.30, 0.35, 1.0), pressed = NewVec4(0.10, 0.10, 0.12, 1.0),
        fontSize = 26,
        onClick = function()
            if _G.GameState == "PLAYING" then
                _G.GameState = "PAUSED"
            end
        end,
    })
    pauseBtn.Offset = NewVec2(0, 0) -- padding away from screen edge
    container:AddChild(pauseBtn)

    return popup, hudText
end

--------------------------------------------------------------------------
-- Module state
--------------------------------------------------------------------------
local _root = nil

local menuPopup = nil
local gameOverPopup = nil
local pausePopup = nil
local hudPopup = nil

local _hudText = nil
local _gameOverScoreText = nil

local _animTimer = 0.0
local _lastScore = nil
local _isEscapeDown = false

--------------------------------------------------------------------------
-- Per-state flourish updates
--------------------------------------------------------------------------

local function UpdateMenu(dt)
    if menuPopup.state == "HIDDEN" then menuPopup:Open() end
    menuPopup:Update(dt)
    if not menuPopup:IsVisible() then return end

    local extraY = 0.0
    if menuPopup.state == "IDLE" then
        extraY = math.sin(_animTimer * FLOAT_SPEED) * FLOAT_AMPLITUDE
    elseif menuPopup.state == "CLOSING" then
        extraY = -CLOSE_LIFT * (menuPopup.progress * menuPopup.progress)
    end
    menuPopup:ApplyVisuals(0, extraY)
end

local function UpdateGameOver(dt)
    if gameOverPopup.state == "HIDDEN" then gameOverPopup:Open() end
    gameOverPopup:Update(dt)

    if _gameOverScoreText then
        _gameOverScoreText.Text = "Final Score: " .. tostring(_G.Score or 0)
    end

    if not gameOverPopup:IsVisible() then return end

    local extraY = 0.0
    local scaleX, scaleY = 1.0, 1.0

    if gameOverPopup.state == "OPENING" then
        local landProgress = Clamp01(gameOverPopup.progress * DROP_SETTLE_MUL)
        local dropOffsetY  = (1.0 - landProgress) * -DROP_HEIGHT
        local wobble       = math.sin(_animTimer * WOBBLE_SPEED) * WOBBLE_AMPLITUDE * (1.0 - landProgress)
        extraY = dropOffsetY + wobble

        local impactPulse = math.max(0.0, 1.0 - math.abs(landProgress - 1.0) * 6.0) * IMPACT_SQUASH
        scaleY = 1.0 - impactPulse
        scaleX = 1.0 + impactPulse * IMPACT_STRETCH

    elseif gameOverPopup.state == "IDLE" then
        extraY = math.sin(_animTimer * WOBBLE_SPEED * 0.5) * IDLE_WOBBLE_AMPLITUDE

    elseif gameOverPopup.state == "CLOSING" then
        extraY = -CLOSE_LIFT * (gameOverPopup.progress * gameOverPopup.progress)
    end
    gameOverPopup:ApplyVisuals(0, extraY, scaleX, scaleY)
end

local function UpdatePause(dt)
    if pausePopup.state == "HIDDEN" then pausePopup:Open() end
    pausePopup:Update(dt)
    if not pausePopup:IsVisible() then return end

    local extraY = 0.0
    if pausePopup.state == "IDLE" then
        extraY = math.sin(_animTimer * FLOAT_SPEED) * IDLE_WOBBLE_AMPLITUDE
    elseif pausePopup.state == "CLOSING" then
        extraY = -CLOSE_LIFT * (pausePopup.progress * pausePopup.progress)
    end
    pausePopup:ApplyVisuals(0, extraY)
end

local function UpdateHUD(dt)
    if hudPopup.state == "HIDDEN" then hudPopup:Open() end
    hudPopup:Update(dt)

    local currentScore = _G.Score or 0
    if hudPopup.state == "IDLE" and _lastScore ~= nil and currentScore ~= _lastScore then
        hudPopup:Punch(1.0)
    end
    _lastScore = currentScore

    hudPopup:ApplyVisuals(0, HUD_OFFSET_Y)

    if _hudText then
        _hudText.Text = "Score: " .. tostring(currentScore) .. " // Lives: " .. tostring(_G.Lives or 3)
    end
end

--------------------------------------------------------------------------
-- Engine callbacks
--------------------------------------------------------------------------

function OnCreate(entity)
    _root = UIWidget.new()

    menuPopup = BuildMainMenu()
    hudPopup, _hudText = BuildHUD()
    gameOverPopup, _gameOverScoreText = BuildGameOver()
    pausePopup = BuildPauseMenu()

    _root:AddChild(menuPopup.container)
    _root:AddChild(hudPopup.container)
    _root:AddChild(gameOverPopup.container)
    _root:AddChild(pausePopup.container)

    SetUIRoot(_root)
end

function OnUpdate(entity, dt)
    _animTimer = _animTimer + dt
    local state = _G.GameState or "MENU"

    -- Global Escape Key Handling
    local escapePressed = Input.IsKeyPressed(Key.Escape)
    if escapePressed and not _isEscapeDown then
        if state == "PLAYING" then
            _G.GameState = "PAUSED"
            state = "PAUSED"
        elseif state == "PAUSED" and pausePopup.state ~= "CLOSING" then
            -- Safely trigger the collapse animation before resuming
            pausePopup:Close(function() _G.GameState = "PLAYING" end)
        end
    end
    _isEscapeDown = escapePressed

    if state == "MENU" then
        UpdateMenu(dt)
        if gameOverPopup:IsVisible() and gameOverPopup.state ~= "CLOSING" then gameOverPopup:HideInstantly() end
        if pausePopup:IsVisible() and pausePopup.state ~= "CLOSING" then pausePopup:HideInstantly() end
        if hudPopup:IsVisible() then hudPopup:HideInstantly() end

    elseif state == "PLAYING" then
        if menuPopup:IsVisible() and menuPopup.state ~= "CLOSING" then menuPopup:HideInstantly() end
        if gameOverPopup:IsVisible() and gameOverPopup.state ~= "CLOSING" then gameOverPopup:HideInstantly() end
        if pausePopup:IsVisible() and pausePopup.state ~= "CLOSING" then pausePopup:HideInstantly() end
        UpdateHUD(dt)

    elseif state == "PAUSED" then
        UpdatePause(dt)
        if menuPopup:IsVisible() and menuPopup.state ~= "CLOSING" then menuPopup:HideInstantly() end
        if gameOverPopup:IsVisible() and gameOverPopup.state ~= "CLOSING" then gameOverPopup:HideInstantly() end
        if hudPopup:IsVisible() then hudPopup:HideInstantly() end

    elseif state == "GAMEOVER" then
        UpdateGameOver(dt)
        if menuPopup:IsVisible() and menuPopup.state ~= "CLOSING" then menuPopup:HideInstantly() end
        if pausePopup:IsVisible() and pausePopup.state ~= "CLOSING" then pausePopup:HideInstantly() end
        if hudPopup:IsVisible() then hudPopup:HideInstantly() end
    end
end

function OnDestroy(entity)
    menuPopup = nil
    gameOverPopup = nil
    pausePopup = nil
    hudPopup = nil
    _hudText = nil
    _gameOverScoreText = nil
    _root = nil
    SetUIRoot(nil)
end